'use client';

/* ============================================================
 * AboutPage = layout of the About page. Texts + pictures are in
 * app/about/page.tsx (you normally do NOT edit this file).
 * ============================================================ */
import { useSelector } from 'react-redux';
import { Target, Eye, ShieldCheck, Clock, Star, Users, Check } from 'lucide-react';
import { RootState } from '../store/store';
import Header from './Header';
import PageHero from './PageHero';
import Footer from './Footer';

type T = { en: string; ar: string };
const ICONS = { target: Target, eye: Eye, shield: ShieldCheck, clock: Clock, star: Star, users: Users };
export type AboutIcon = keyof typeof ICONS;

export interface AboutData {
  slides: string[];
  hero: { badge: T; title: T; text: T };
  story: { badge: T; title: T; paragraphs: T[]; points: T[]; image: string };
  stats: { value: string; label: T }[];
  pillars: { icon: AboutIcon; title: T; text: T }[]; // mission / vision / values cards
}

function Eyebrow({ text }: { text: string }) {
  return (
    <div className="inline-flex items-center gap-1.5 text-[11px] sm:text-xs font-bold uppercase tracking-widest text-[#d9a036]">
      <span className="w-6 h-[2px] bg-[#d9a036]" />
      <span>{text}</span>
    </div>
  );
}

export default function AboutPage({ data }: { data: AboutData }) {
  const isAr = useSelector((state: RootState) => state.language.lang) === 'AR';
  const L = (t: T) => (isAr ? t.ar : t.en);

  return (
    <main className="min-h-screen bg-gray-50" dir={isAr ? 'rtl' : 'ltr'}>
      <Header />
      <PageHero slides={data.slides} badge={data.hero.badge} title={data.hero.title} text={data.hero.text} />

      {/* Our story: text + picture */}
      <section className="py-16 sm:py-20 bg-white">
        <div className="w-[90%] max-w-[2000px] mx-auto grid grid-cols-1 lg:grid-cols-2 gap-10 lg:gap-14 items-center">
          <div className="space-y-5">
            <Eyebrow text={L(data.story.badge)} />
            <h2 className="text-2xl sm:text-3xl lg:text-4xl font-black text-gray-900 tracking-tight leading-tight">{L(data.story.title)}</h2>
            {data.story.paragraphs.map((p, i) => (
              <p key={i} className="text-gray-600 text-sm leading-relaxed font-medium">{L(p)}</p>
            ))}
            <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2">
              {data.story.points.map((pt, i) => (
                <li key={i} className="flex items-start gap-2.5 text-xs sm:text-sm font-semibold text-gray-800">
                  <span className="mt-0.5 w-5 h-5 rounded-full bg-[#d9a036]/15 text-[#d9a036] flex items-center justify-center shrink-0">
                    <Check className="w-3 h-3 stroke-[3]" />
                  </span>
                  {L(pt)}
                </li>
              ))}
            </ul>
          </div>
          <div className="relative rounded-2xl overflow-hidden shadow-xl border border-gray-100 aspect-[16/10] bg-gray-100">
            <img src={data.story.image} alt="" loading="lazy" className="absolute inset-0 w-full h-full object-cover" />
          </div>
        </div>
      </section>

      {/* Numbers */}
      <section className="py-12 sm:py-14 bg-[#181818]">
        <div className="w-[90%] max-w-[2000px] mx-auto grid grid-cols-2 lg:grid-cols-4 gap-8 text-center">
          {data.stats.map((st, i) => (
            <div key={i}>
              <h3 className="text-3xl sm:text-4xl font-black text-[#d9a036]" dir="ltr">{st.value}</h3>
              <p className="text-[11px] sm:text-xs text-gray-300 font-bold uppercase tracking-wider mt-2">{L(st.label)}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Mission, vision, values */}
      <section className="py-16 sm:py-20 bg-gray-50/50">
        <div className="w-[90%] max-w-[2000px] mx-auto">
          <div className="text-center space-y-2 mb-12">
            <div className="inline-flex"><Eyebrow text={isAr ? 'ما نؤمن به' : 'WHAT WE STAND FOR'} /></div>
            <h2 className="text-2xl sm:text-3xl lg:text-4xl font-black text-gray-900 tracking-tight">
              {isAr ? 'رسالتنا ورؤيتنا وقيمنا' : 'Our Mission, Vision And Values'}
            </h2>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {data.pillars.map((item, i) => {
              const Icon = ICONS[item.icon] ?? Star;
              return (
                <div key={i} className="bg-white rounded-2xl border border-gray-100 p-7 shadow-sm hover:shadow-md transition-all duration-300 group">
                  <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[#f3d38c] to-[#d9a036] flex items-center justify-center shadow-md group-hover:scale-105 transition-transform duration-300 mb-5">
                    <Icon className="w-7 h-7 text-white stroke-[2.2]" />
                  </div>
                  <h3 className="text-base sm:text-lg font-bold text-gray-900 mb-2">{L(item.title)}</h3>
                  <p className="text-xs sm:text-[13px] text-gray-500 leading-relaxed font-medium">{L(item.text)}</p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      <Footer />
    </main>
  );
}
